"""Generate MT0 test vectors (pitches, intervals) with music21.

Run from the repo root:
    uv run --with music21==10.5.2 python -I tests/fixtures/generate-mt0.py

Writes tests/fixtures/mt0-pitches.sexp and tests/fixtures/mt0-intervals.sexp.
The values are computed facts (MIDI numbers, interval sizes and names);
music21 (BSD-3-Clause) is only the oracle. See PROVENANCE.md.
"""
from pathlib import Path
from music21 import pitch, interval

LETTERS = "CDEFGAB"
BASE_FIFTHS = {"C": 0, "G": 1, "D": 2, "A": 3, "E": 4, "B": 5, "F": -1}
ASCII = {-2: "bb", -1: "b", 0: "", 1: "#", 2: "##"}
M21 = {-2: "--", -1: "-", 0: "", 1: "#", 2: "##"}
OUT = Path(__file__).resolve().parent


def ours(letter, alter, octave):
    return f"{letter}{ASCII[alter]}{octave}"


def m21(letter, alter, octave):
    return pitch.Pitch(f"{letter}{M21[alter]}{octave}")


def lisp_string(s):
    return '"' + s.replace("\\", "\\\\").replace('"', '\\"') + '"'


rows = []
for octave in range(0, 9):
    for letter in LETTERS:
        for alter in range(-2, 3):
            p = m21(letter, alter, octave)
            rows.append(f"({lisp_string(ours(letter, alter, octave))} {p.midi} "
                        f"{BASE_FIFTHS[letter] + 7 * alter} {p.pitchClass})")
(OUT / "mt0-pitches.sexp").write_text(
    ";; (name midi fifths pitch-class), generated by generate-mt0.py with music21 10.5.2\n("
    + "\n ".join(rows) + ")\n")

classes = [(l, a) for l in LETTERS for a in range(-2, 3)]
in_range, out_of_range = [], []
for (pl, pa) in classes:
    for oq in (3, 4, 5):
        for (ql, qa) in classes:
            p, q = m21(pl, pa, 4), m21(ql, qa, oq)
            try:
                i = interval.Interval(p, q)
            except interval.IntervalException:
                # Too far off for music21 to name: record the sizes only.
                steps = (q.diatonicNoteNum - p.diatonicNoteNum)
                out_of_range.append(
                    f"({lisp_string(ours(pl, pa, 4))} {lisp_string(ours(ql, qa, oq))} "
                    f"{steps} {int(q.midi - p.midi)} nil)")
                continue
            g = i.generic.directed
            steps = (abs(g) - 1) * (1 if g > 0 else -1)
            name = i.name if g > 0 or steps == 0 else "-" + i.name
            row = (f"({lisp_string(ours(pl, pa, 4))} {lisp_string(ours(ql, qa, oq))} "
                   f"{steps} {int(i.semitones)} {lisp_string(name)})")
            core = i.name.lstrip("-")
            quality = core.rstrip("0123456789")
            (out_of_range if len(quality) > 2 else in_range).append(row)
(OUT / "mt0-intervals.sexp").write_text(
    ";; (from to steps semitones name), generated by generate-mt0.py with music21 10.5.2\n"
    ";; Only intervals up to doubly augmented / doubly diminished.\n("
    + "\n ".join(in_range) + ")\n")
(OUT / "mt0-intervals-out-of-range.sexp").write_text(
    ";; (from to steps semitones music21-name): triply augmented / diminished and beyond.\n"
    ";; Our model names qualities only up to AA / dd, so INTERVAL-NAME signals INVALID-INTERVAL.\n("
    + "\n ".join(out_of_range) + ")\n")
print(len(rows), "pitches;", len(in_range), "intervals;", len(out_of_range), "out of range")
